(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["anatomy-exam-3-endocrine-exam3-quiz"]={"title":"Endocrine System Practice Exam — Anatomy Exam 3","category":"Anatomy","sem":"summer-1-2026","questions":[{"q":"Which structure is considered a primary endocrine organ?","choices":["Stomach","Pituitary gland","Small intestine","Liver"],"answer":1,"exp":"The pituitary is a primary endocrine organ."},{"q":"Which organ has endocrine functions but is not primarily classified as an endocrine gland?","choices":["Thyroid gland","Parathyroid gland","Heart","Pituitary gland"],"answer":2,"exp":"The heart has endocrine functions but is not primarily an endocrine gland."},{"q":"Which hormone is produced by adipose tissue?","choices":["Calcitonin","Leptin","Aldosterone","Oxytocin"],"answer":1,"exp":"Adipose tissue produces leptin."},{"q":"The kidney performs an endocrine function by producing","choices":["prolactin and growth hormone","calcitriol and erythropoietin","insulin and glucagon","cortisol and aldosterone"],"answer":1,"exp":"The kidney produces erythropoietin and calcitriol."},{"q":"The endocrine system differs from an exocrine system because endocrine glands","choices":["release products through ducts","release hormones into the bloodstream","contain only nervous tissue","secrete only steroid hormones"],"answer":1,"exp":"Endocrine glands release hormones into blood rather than through ducts."},{"q":"Which organ produces atrial natriuretic peptide?","choices":["Adrenal gland","Heart","Kidney","Thyroid gland"],"answer":1,"exp":"The heart produces ANP."},{"q":"Which organ produces melatonin?","choices":["Pineal gland","Pituitary gland","Pancreas","Thymus"],"answer":0,"exp":"The pineal gland produces melatonin."},{"q":"Which structure produces thymosins?","choices":["Thyroid","Thymus","Hypothalamus","Adrenal cortex"],"answer":1,"exp":"The thymus produces thymosins."},{"q":"The pituitary gland is also called the","choices":["epiphysis","hypophysis","thymus","neurocranium"],"answer":1,"exp":"Pituitary gland = hypophysis."},{"q":"The pituitary gland is attached to the hypothalamus by the","choices":["fornix","optic tract","infundibulum","corpus callosum"],"answer":2,"exp":"The infundibulum connects the pituitary to the hypothalamus."},{"q":"The pituitary gland lies within the","choices":["cribriform plate","hypophyseal fossa","jugular foramen","foramen magnum"],"answer":1,"exp":"The pituitary occupies the hypophyseal fossa."},{"q":"The hypophyseal fossa is located within the","choices":["ethmoid bone","temporal bone","sphenoid bone","occipital bone"],"answer":2,"exp":"The sella turcica is part of the sphenoid bone."},{"q":"Which structure lies directly superior to the pituitary gland?","choices":["Sphenoid sinus","Optic chiasm","Dorsum sellae","Nasopharynx"],"answer":1,"exp":"The optic chiasm lies superior to the pituitary."},{"q":"Which structure lies inferior and anterior to the pituitary gland?","choices":["Sphenoid sinus","Cavernous sinus","Optic tract","Third ventricle"],"answer":0,"exp":"The sphenoid sinus lies inferior and anterior to the pituitary."},{"q":"The pituitary gland is related laterally to the","choices":["sagittal sinuses","cavernous sinuses","transverse sinuses","sigmoid sinuses"],"answer":1,"exp":"The cavernous sinuses lie lateral to the pituitary."},{"q":"The structure located posterior to the pituitary gland is the","choices":["crista galli","dorsum sellae","clivus only","optic chiasm"],"answer":1,"exp":"The dorsum sellae lies posterior to the gland."},{"q":"The dural structure covering the superior aspect of the pituitary is the","choices":["falx cerebri","tentorium cerebelli","diaphragma sellae","falx cerebelli"],"answer":2,"exp":"The diaphragma sellae covers the gland superiorly."},{"q":"The diaphragma sellae is pierced by the","choices":["optic nerve","internal carotid artery","infundibulum","oculomotor nerve"],"answer":2,"exp":"The infundibulum pierces the diaphragma sellae."},{"q":"A pituitary mass growing superiorly is most likely to compress the","choices":["vagus nerve","optic chiasm","facial nerve","olfactory bulb"],"answer":1,"exp":"Superior growth may compress the optic chiasm."},{"q":"Compression of the optic chiasm by a pituitary tumor classically produces","choices":["monocular blindness","bitemporal hemianopia","left homonymous hemianopia","central scotoma only"],"answer":1,"exp":"Optic chiasm compression causes bitemporal hemianopia."},{"q":"A pituitary mass extending laterally may involve the","choices":["cavernous sinus","frontal sinus","superior sagittal sinus","straight sinus"],"answer":0,"exp":"Lateral extension may enter the cavernous sinus."},{"q":"Which structure is part of the adenohypophysis?","choices":["Pars nervosa","Infundibulum","Pars distalis","Hypothalamo-hypophyseal tract"],"answer":2,"exp":"Pars distalis belongs to the adenohypophysis."},{"q":"Which structure is part of the neurohypophysis?","choices":["Pars distalis","Pars tuberalis","Pars intermedia","Pars nervosa"],"answer":3,"exp":"Pars nervosa belongs to the neurohypophysis."},{"q":"The adenohypophysis includes all of the following except","choices":["pars distalis","pars tuberalis","pars intermedia","pars nervosa"],"answer":3,"exp":"Pars nervosa is not part of the adenohypophysis."},{"q":"The posterior pituitary is connected to the hypothalamus by the","choices":["mammillothalamic tract","infundibulum","optic radiation","fornix"],"answer":1,"exp":"The posterior lobe connects through the infundibulum."},{"q":"Which hormones are synthesized in the hypothalamus and released from the posterior pituitary?","choices":["TSH and ACTH","GH and prolactin","ADH and oxytocin","FSH and LH"],"answer":2,"exp":"ADH and oxytocin are made in the hypothalamus and released posteriorly."},{"q":"The anterior pituitary receives blood mainly through the","choices":["systemic venous system only","hypophyseal portal system","cerebral aqueduct","superior sagittal sinus"],"answer":1,"exp":"The anterior pituitary receives portal blood."},{"q":"The posterior pituitary receives primarily","choices":["portal venous blood","lymphatic blood","direct arterial blood","blood from the internal jugular vein"],"answer":2,"exp":"The posterior pituitary receives direct arterial blood."},{"q":"The primary capillary plexus of the hypophyseal portal system is associated with the","choices":["median eminence","pars nervosa","sphenoid sinus","cavernous sinus"],"answer":0,"exp":"The primary capillary plexus is at the median eminence."},{"q":"The hypophyseal portal vessels carry regulatory hormones from the hypothalamus to the","choices":["posterior pituitary","anterior pituitary","thyroid gland","adrenal medulla"],"answer":1,"exp":"Portal veins carry regulatory hormones to the anterior pituitary."},{"q":"Which artery is most closely associated with the primary capillary plexus supplying the anterior pituitary?","choices":["Inferior thyroid artery","Superior hypophyseal artery","Middle cerebral artery","Posterior communicating artery"],"answer":1,"exp":"The superior hypophyseal artery supplies the portal system."},{"q":"Which artery primarily supplies the posterior pituitary?","choices":["Inferior hypophyseal artery","Superior thyroid artery","Superior cerebellar artery","Anterior spinal artery"],"answer":0,"exp":"The inferior hypophyseal artery mainly supplies the posterior lobe."},{"q":"Which anterior pituitary cell produces growth hormone?","choices":["Thyrotrope","Gonadotrope","Somatotrope","Corticotrope"],"answer":2,"exp":"Somatotropes produce GH."},{"q":"Which anterior pituitary cell produces prolactin?","choices":["Lactotrope","Thyrotrope","Corticotrope","Gonadotrope"],"answer":0,"exp":"Lactotropes produce prolactin."},{"q":"Which cells produce FSH and LH?","choices":["Somatotropes","Gonadotropes","Lactotropes","Pituicytes"],"answer":1,"exp":"Gonadotropes produce FSH and LH."},{"q":"Which cell produces TSH?","choices":["Thyrotrope","Somatotrope","Chromaffin cell","Chief cell"],"answer":0,"exp":"Thyrotropes produce TSH."},{"q":"ACTH is released primarily by","choices":["corticotropes","lactotropes","somatotropes","thyrotropes"],"answer":0,"exp":"Corticotropes release ACTH."},{"q":"Chromophobes are characterized by","choices":["abundant secretory granules","no visible cytoplasmic granules","storage of colloid","production of calcitonin"],"answer":1,"exp":"Chromophobes lack visible cytoplasmic granules."},{"q":"Acidophils of the anterior pituitary produce","choices":["GH and prolactin","TSH and ACTH","FSH and LH only","ADH and oxytocin"],"answer":0,"exp":"Acidophils produce GH and prolactin."},{"q":"Basophils of the anterior pituitary produce all of the following except","choices":["TSH","ACTH","FSH","GH"],"answer":3,"exp":"GH is produced by acidophils, not basophils."},{"q":"Which structure is characteristic of the posterior pituitary?","choices":["Thyroid follicles","Herring bodies","Pancreatic acini","Adrenal glomeruli"],"answer":1,"exp":"Herring bodies are found in the posterior pituitary."},{"q":"Pituicytes are","choices":["endocrine cells of the anterior pituitary","supporting glial cells of the posterior pituitary","thyroid follicular cells","adrenal cortical cells"],"answer":1,"exp":"Pituicytes are supporting glial cells."},{"q":"The hypothalamo-hypophyseal tract consists primarily of","choices":["venous channels","hypothalamic axons","lymphatic vessels","smooth muscle fibers"],"answer":1,"exp":"The hypothalamo-hypophyseal tract consists of hypothalamic axons."},{"q":"Herring bodies represent accumulations of","choices":["colloid and thyroglobulin","stored neurosecretory material","steroid droplets","insulin granules"],"answer":1,"exp":"Herring bodies store neurosecretory material."},{"q":"The thyroid gland lies approximately between vertebral levels","choices":["C1-C3","C5-T1","T4-T7","T10-L1"],"answer":1,"exp":"The thyroid extends approximately from C5 to T1."},{"q":"The thyroid gland is composed primarily of","choices":["four lobes without an isthmus","two lobes connected by an isthmus","one midline lobe","two lobes connected by the pyramidal process only"],"answer":1,"exp":"It has two lobes connected by an isthmus."},{"q":"The apex of each thyroid lobe lies near the","choices":["hyoid bone only","oblique line of the thyroid cartilage","sixth tracheal ring","sternoclavicular joint"],"answer":1,"exp":"The apex reaches the oblique line of the thyroid cartilage."},{"q":"The base of each thyroid lobe is located approximately at the level of the","choices":["first tracheal ring","fourth or fifth tracheal ring","cricoid cartilage only","hyoid bone"],"answer":1,"exp":"The base lies near the fourth or fifth tracheal ring."},{"q":"The thyroid isthmus usually overlies the","choices":["first cervical vertebra","second and third tracheal rings","sixth and seventh tracheal rings","upper esophagus"],"answer":1,"exp":"The isthmus usually overlies the second and third tracheal rings."},{"q":"Which muscles cover the thyroid isthmus anteriorly?","choices":["Sternocleidomastoid and trapezius","Sternohyoid and sternothyroid","Thyrohyoid and digastric","Mylohyoid and geniohyoid"],"answer":1,"exp":"Sternohyoid and sternothyroid cover the isthmus."},{"q":"The thyroid gland moves during swallowing because it is attached to the laryngeal framework through the","choices":["carotid sheath","pretracheal fascia","prevertebral fascia","alar fascia"],"answer":1,"exp":"The pretracheal fascia causes the thyroid to move with swallowing."},{"q":"The medial surface of the thyroid is related to all of the following except","choices":["trachea","esophagus","larynx","parotid gland"],"answer":3,"exp":"The parotid gland is not a medial thyroid relation."},{"q":"Which nerve is closely related to the tracheoesophageal groove and medial thyroid surface?","choices":["Phrenic nerve","Recurrent laryngeal nerve","Accessory nerve","Hypoglossal nerve"],"answer":1,"exp":"The recurrent laryngeal nerve lies near the tracheoesophageal groove."},{"q":"The external laryngeal nerve is especially related to the","choices":["superior thyroid artery","inferior thyroid vein","middle thyroid vein","thyroidea ima artery"],"answer":0,"exp":"The external laryngeal nerve is closely related to the superior thyroid artery."},{"q":"The posterior surface of the thyroid is related laterally to the","choices":["carotid sheath","vertebral artery","thoracic duct only","submandibular gland"],"answer":0,"exp":"The posterior thyroid surface is related to the carotid sheath."},{"q":"Which structure is normally lateral to the common carotid artery within the carotid sheath?","choices":["Vagus nerve","Internal jugular vein","Recurrent laryngeal nerve","Sympathetic trunk"],"answer":1,"exp":"The internal jugular vein lies lateral to the carotid artery."},{"q":"The vagus nerve is contained within the","choices":["pretracheal fascia","carotid sheath","thyroid capsule","retropharyngeal space"],"answer":1,"exp":"The vagus nerve is contained in the carotid sheath."},{"q":"A pyramidal lobe of the thyroid most commonly arises from the","choices":["lower border of the right lobe","upper border of the isthmus","posterior surface of the left lobe","inferior thyroid artery"],"answer":1,"exp":"The pyramidal lobe commonly arises from the superior isthmus."},{"q":"The levator glandulae thyroideae may connect the pyramidal lobe to the","choices":["mandible","hyoid bone","clavicle","sternum"],"answer":1,"exp":"The levator glandulae thyroideae may connect to the hyoid bone."},{"q":"The structural unit of the thyroid gland is the","choices":["acinus","follicle","lobule of Langerhans","zona fasciculata"],"answer":1,"exp":"The thyroid follicle is the structural unit of the gland."},{"q":"A thyroid follicle is lined primarily by","choices":["stratified squamous epithelium","simple cuboidal epithelium","pseudostratified columnar epithelium","transitional epithelium"],"answer":1,"exp":"Thyroid follicles are lined by simple cuboidal epithelium."},{"q":"The central material within a thyroid follicle is called","choices":["medulla","colloid","cortex","sinusoid"],"answer":1,"exp":"The central follicular material is colloid."},{"q":"Highly active thyroid follicles generally contain","choices":["flatter epithelial cells","taller epithelial cells","no colloid","stratified epithelium"],"answer":1,"exp":"Active follicles have taller epithelial cells."},{"q":"Parafollicular cells secrete","choices":["parathyroid hormone","calcitonin","TSH","thyroglobulin"],"answer":1,"exp":"Parafollicular cells secrete calcitonin."},{"q":"Parafollicular cells are also called","choices":["chief cells","C cells","chromaffin cells","oxyphil cells"],"answer":1,"exp":"Parafollicular cells are also called C cells."},{"q":"The superior thyroid artery usually arises from the","choices":["common carotid artery","external carotid artery","subclavian artery","aortic arch"],"answer":1,"exp":"The superior thyroid artery arises from the external carotid artery."},{"q":"The inferior thyroid artery usually arises from the","choices":["thyrocervical trunk","external carotid artery","common carotid artery","internal thoracic artery"],"answer":0,"exp":"The inferior thyroid artery arises from the thyrocervical trunk."},{"q":"The thyrocervical trunk is a branch of the","choices":["external carotid artery","subclavian artery","brachiocephalic vein","descending thoracic aorta"],"answer":1,"exp":"The thyrocervical trunk comes from the subclavian artery."},{"q":"The inferior thyroid artery is closely related to the","choices":["facial nerve","recurrent laryngeal nerve","optic nerve","hypoglossal nerve only"],"answer":1,"exp":"The inferior thyroid artery is related to the recurrent laryngeal nerve."},{"q":"The thyroidea ima artery is","choices":["always present","an uncommon arterial variant","a branch of the internal carotid artery","the main supply to the thyroid lobes"],"answer":1,"exp":"The thyroidea ima is an uncommon variant."},{"q":"The thyroidea ima artery may arise from the","choices":["brachiocephalic artery or aortic arch","external carotid artery only","vertebral artery","axillary artery"],"answer":0,"exp":"It may arise from the brachiocephalic artery or aortic arch."},{"q":"The superior and middle thyroid veins usually drain into the","choices":["external jugular vein","internal jugular vein","azygos vein","subclavian artery"],"answer":1,"exp":"Superior and middle thyroid veins drain to the internal jugular vein."},{"q":"The inferior thyroid veins usually drain into the","choices":["brachiocephalic veins","internal carotid artery","superior sagittal sinus","facial vein"],"answer":0,"exp":"Inferior thyroid veins drain to the brachiocephalic veins."},{"q":"Thyroid lymphatic drainage includes the","choices":["paratracheal and deep cervical nodes","axillary nodes only","inguinal nodes","popliteal nodes"],"answer":0,"exp":"Thyroid lymph drains to paratracheal and deep cervical nodes."},{"q":"The parathyroid glands are usually located","choices":["on the anterior thyroid surface","along the posterior thyroid surface","inside the pituitary fossa","within the adrenal medulla"],"answer":1,"exp":"Parathyroids lie on the posterior thyroid surface."},{"q":"The usual number of parathyroid glands is","choices":["two","three","four","six"],"answer":2,"exp":"Four glands are most common."},{"q":"The superior parathyroid glands are generally","choices":["more variable in location","more constant in location","always inside the thyroid","located in the mediastinum"],"answer":1,"exp":"Superior parathyroids are more constant in position."},{"q":"The inferior parathyroid glands may be found","choices":["only at the upper thyroid pole","above or below the inferior thyroid arteries","only inside the carotid artery","within the pituitary gland"],"answer":1,"exp":"Inferior glands may lie above or below the inferior thyroid arteries."},{"q":"The primary hormone-secreting cells of the parathyroid are the","choices":["follicular cells","principal or chief cells","chromaffin cells","somatotropes"],"answer":1,"exp":"Chief cells are the main hormone-producing cells."},{"q":"Chief cells produce","choices":["calcitonin","PTH","cortisol","insulin"],"answer":1,"exp":"Chief cells produce PTH."},{"q":"Oxyphil cells are described as","choices":["small and basophilic","larger and strongly eosinophilic","filled with colloid","modified neurons"],"answer":1,"exp":"Oxyphil cells are larger and eosinophilic."},{"q":"Which finding commonly increases in the parathyroid gland with age?","choices":["Colloid","Adipose tissue","Cartilage","Skeletal muscle"],"answer":1,"exp":"Adipose tissue increases with age."},{"q":"The parathyroid glands are closely related to the","choices":["tracheoesophageal groove","optic chiasm","sphenoid sinus","splenic hilum"],"answer":0,"exp":"Parathyroids lie near the tracheoesophageal groove."},{"q":"The parathyroid glands generally share their vascular, lymphatic, and nerve supply with the","choices":["pancreas","thyroid gland","pituitary gland","adrenal gland"],"answer":1,"exp":"Their vascular, nerve, and lymph supply generally follows the thyroid."},{"q":"The pancreas lies primarily in the","choices":["hypogastric and right iliac regions","epigastric and left hypochondriac regions","right hypochondriac region only","pelvic cavity"],"answer":1,"exp":"The pancreas lies mainly in the epigastric and left hypochondriac regions."},{"q":"Most of the pancreas is","choices":["intraperitoneal","retroperitoneal","within the lesser omentum","contained in the mesocolon"],"answer":1,"exp":"Most of the pancreas is retroperitoneal."},{"q":"The head of the pancreas lies within the","choices":["concavity of the duodenum","splenic hilum","liver fissure","renal pelvis"],"answer":0,"exp":"The head lies in the duodenal concavity."},{"q":"The tail of the pancreas extends toward the","choices":["gallbladder","spleen","right kidney","cecum"],"answer":1,"exp":"The tail extends toward the spleen."},{"q":"The body of the pancreas crosses anterior to the","choices":["left kidney","urinary bladder","uterus","right atrium"],"answer":0,"exp":"The body crosses anterior to the left kidney."},{"q":"The pancreas is related anteriorly to the","choices":["transverse colon","aorta only","inferior vena cava only","vertebral canal"],"answer":0,"exp":"The transverse colon is anteriorly related."},{"q":"The aorta and inferior vena cava lie primarily","choices":["anterior to the pancreas","posterior to the pancreas","within the pancreatic duct","lateral to the tail only"],"answer":1,"exp":"The aorta and IVC lie posterior to the pancreas."},{"q":"The uncinate process lies","choices":["anterior to the SMA and SMV","posterior to the SMA and SMV","inside the spleen","within the lesser omentum"],"answer":1,"exp":"The uncinate process lies posterior to the SMA and SMV."},{"q":"The uncinate process lies anterior to the","choices":["aorta","stomach","liver","transverse colon"],"answer":0,"exp":"It lies anterior to the aorta."},{"q":"The neck of the pancreas lies anterior to the","choices":["SMV","splenic artery only","IVC only","left ureter"],"answer":0,"exp":"The pancreatic neck lies anterior to the SMV."},{"q":"Which vessel runs along the superior border of the pancreatic body and tail?","choices":["Inferior mesenteric artery","Splenic artery","Renal artery","Cystic artery"],"answer":1,"exp":"The splenic artery travels along the superior border."},{"q":"The splenic vein lies primarily","choices":["on the anterior surface of the pancreas","on the posterior surface of the pancreas","within the common bile duct","inside the pancreatic duct"],"answer":1,"exp":"The splenic vein lies on the posterior pancreatic surface."},{"q":"The splenic vein ultimately contributes to formation of the","choices":["inferior vena cava","portal vein","azygos vein","external iliac vein"],"answer":1,"exp":"The splenic vein helps form the portal vein."},{"q":"The common bile duct passes through or behind the","choices":["tail of the pancreas","head of the pancreas","splenic hilum","adrenal cortex"],"answer":1,"exp":"The common bile duct passes behind or through the pancreatic head."},{"q":"The common bile duct and main pancreatic duct commonly unite at the","choices":["minor papilla","hepatopancreatic ampulla","cystic duct","pyloric canal"],"answer":1,"exp":"It joins the main pancreatic duct at the hepatopancreatic ampulla."},{"q":"The hepatopancreatic ampulla is also called the ampulla of","choices":["Santorini","Vater","Wirsung","Treitz"],"answer":1,"exp":"The hepatopancreatic ampulla is the ampulla of Vater."},{"q":"The main pancreatic duct is the duct of","choices":["Santorini","Wirsung","Vater","Oddi"],"answer":1,"exp":"Main pancreatic duct = duct of Wirsung."},{"q":"The accessory pancreatic duct is the duct of","choices":["Santorini","Wirsung","Vater","Treitz"],"answer":0,"exp":"Accessory pancreatic duct = duct of Santorini."},{"q":"The accessory pancreatic duct opens into the duodenum at the","choices":["major papilla","minor papilla","ileocecal valve","pyloric sphincter"],"answer":1,"exp":"Santorini opens at the minor duodenal papilla."},{"q":"The main pancreatic duct usually opens through the","choices":["minor duodenal papilla","major duodenal papilla","ileal papilla","gastric cardia"],"answer":1,"exp":"Wirsung usually opens at the major duodenal papilla."},{"q":"The head of the pancreas is supplied primarily by","choices":["superior and inferior pancreaticoduodenal arteries","left gastric artery only","inferior mesenteric artery","cystic artery"],"answer":0,"exp":"The head receives superior and inferior pancreaticoduodenal arteries."},{"q":"The superior pancreaticoduodenal arteries arise from the","choices":["gastroduodenal artery","inferior mesenteric artery","splenic artery only","renal artery"],"answer":0,"exp":"Superior pancreaticoduodenal branches come from the gastroduodenal artery."},{"q":"The inferior pancreaticoduodenal arteries arise from the","choices":["superior mesenteric artery","celiac trunk directly","inferior mesenteric artery","common iliac artery"],"answer":0,"exp":"Inferior pancreaticoduodenal branches come from the SMA."},{"q":"The body and tail of the pancreas receive arterial supply primarily from branches of the","choices":["splenic artery","inferior mesenteric artery","cystic artery","middle suprarenal artery"],"answer":0,"exp":"The body and tail receive branches from the splenic artery."},{"q":"Pancreatic carcinoma occurs most commonly in the","choices":["tail","head","body only","accessory duct only"],"answer":1,"exp":"Pancreatic carcinoma commonly occurs in the head."},{"q":"A tumor in the pancreatic head may obstruct the","choices":["common bile duct","ureter","renal artery","inferior mesenteric vein"],"answer":0,"exp":"A pancreatic head tumor can obstruct the common bile duct."},{"q":"Most pancreatic tissue is composed of","choices":["thyroid follicles","exocrine acini","adrenal cortex","pituitary chromophobes"],"answer":1,"exp":"Most pancreatic tissue consists of exocrine acini."},{"q":"The endocrine portion of the pancreas is formed by the","choices":["islets of Langerhans","acini of Wirsung","follicles of Santorini","glomeruli of Vater"],"answer":0,"exp":"The endocrine tissue is organized into islets of Langerhans."},{"q":"Beta cells produce","choices":["glucagon","insulin","somatostatin","pancreatic polypeptide"],"answer":1,"exp":"Beta cells produce insulin."},{"q":"Alpha cells produce","choices":["insulin","glucagon","calcitonin","aldosterone"],"answer":1,"exp":"Alpha cells produce glucagon."},{"q":"Delta cells produce","choices":["somatostatin","cortisol","thyroxine","prolactin"],"answer":0,"exp":"Delta cells produce somatostatin."},{"q":"F cells produce","choices":["pancreatic polypeptide","growth hormone","calcitriol","epinephrine"],"answer":0,"exp":"F cells produce pancreatic polypeptide."},{"q":"Pancreatic islets are highly vascularized and contain","choices":["continuous capillaries only","fenestrated capillaries","no capillaries","lymphatic sinusoids only"],"answer":1,"exp":"Endocrine islets contain fenestrated capillaries."},{"q":"The adrenal glands are also called","choices":["pararenal glands","suprarenal glands","hypophyseal glands","pineal glands"],"answer":1,"exp":"Adrenal glands are also called suprarenal glands."},{"q":"The adrenal glands lie","choices":["inferior to the kidneys","on the superior poles of the kidneys","inside the renal pelvis","anterior to the bladder"],"answer":1,"exp":"They sit on the superior poles of the kidneys."},{"q":"The right adrenal gland is typically","choices":["semilunar","pyramidal","spherical","bilobed"],"answer":1,"exp":"The right adrenal gland is pyramidal."},{"q":"The left adrenal gland is typically","choices":["pyramidal","semilunar","triangular only","cuboidal"],"answer":1,"exp":"The left adrenal gland is semilunar."},{"q":"The right adrenal gland is related anteriorly to the","choices":["liver and IVC","stomach and pancreas","spleen and jejunum","descending colon only"],"answer":0,"exp":"The right gland is anteriorly related to the liver and IVC."},{"q":"The left adrenal gland is related anteriorly to the","choices":["liver and IVC","stomach and pancreas","duodenum and gallbladder","cecum and appendix"],"answer":1,"exp":"The left gland is anteriorly related to the stomach and pancreas."},{"q":"Both adrenal glands are related posteriorly to the","choices":["diaphragm","stomach","pancreas","liver only"],"answer":0,"exp":"Both are posteriorly related to the diaphragm."},{"q":"The inferior relation of each adrenal gland is the","choices":["thyroid gland","kidney","spleen","duodenum"],"answer":1,"exp":"Each adrenal gland rests superior to a kidney."},{"q":"The superior suprarenal arteries arise from the","choices":["inferior phrenic arteries","renal arteries","abdominal aorta directly","celiac trunk"],"answer":0,"exp":"Superior suprarenal arteries arise from inferior phrenic arteries."},{"q":"The middle suprarenal arteries arise directly from the","choices":["abdominal aorta","renal arteries","inferior phrenic arteries","superior mesenteric artery"],"answer":0,"exp":"Middle suprarenal arteries arise directly from the aorta."},{"q":"The inferior suprarenal arteries arise from the","choices":["renal arteries","splenic artery","common hepatic artery","inferior mesenteric artery"],"answer":0,"exp":"Inferior suprarenal arteries arise from renal arteries."},{"q":"The right suprarenal vein drains directly into the","choices":["left renal vein","inferior vena cava","portal vein","splenic vein"],"answer":1,"exp":"The right suprarenal vein drains directly to the IVC."},{"q":"The left suprarenal vein drains primarily into the","choices":["inferior vena cava directly","left renal vein","portal vein","azygos vein"],"answer":1,"exp":"The left suprarenal vein drains to the left renal vein."},{"q":"Which adrenal gland generally has a shorter vein?","choices":["Left","Right","Both are equal","Neither has a vein"],"answer":1,"exp":"The right suprarenal vein is shorter."},{"q":"The adrenal gland is divided into","choices":["follicles and colloid","cortex and medulla","anterior and posterior lobes","acini and islets"],"answer":1,"exp":"The gland has cortex and medulla."},{"q":"The outermost adrenal cortical zone is the","choices":["zona reticularis","zona fasciculata","zona glomerulosa","medulla"],"answer":2,"exp":"Zona glomerulosa is the outermost cortical layer."},{"q":"The middle adrenal cortical zone is the","choices":["zona glomerulosa","zona fasciculata","zona reticularis","pars distalis"],"answer":1,"exp":"Zona fasciculata is the middle cortical layer."},{"q":"The innermost cortical zone is the","choices":["zona reticularis","zona fasciculata","zona glomerulosa","medulla"],"answer":0,"exp":"Zona reticularis is the innermost cortical layer."},{"q":"The zona glomerulosa produces primarily","choices":["mineralocorticoids","glucocorticoids","catecholamines","thyroid hormones"],"answer":0,"exp":"Zona glomerulosa produces mineralocorticoids."},{"q":"The zona fasciculata produces primarily","choices":["aldosterone","cortisol","epinephrine","calcitonin"],"answer":1,"exp":"Zona fasciculata produces cortisol."},{"q":"The zona reticularis produces primarily","choices":["androgens","insulin","catecholamines","PTH"],"answer":0,"exp":"Zona reticularis produces androgens."},{"q":"Cells of the zona fasciculata are arranged mainly in","choices":["spherical follicles","radial columns","isolated islets","nerve bundles"],"answer":1,"exp":"Fasciculata cells form radial columns."},{"q":"The principal cells of the adrenal medulla are","choices":["chief cells","chromaffin cells","follicular cells","pituicytes"],"answer":1,"exp":"Chromaffin cells are the main adrenal medullary cells."},{"q":"Chromaffin cells are functionally comparable to modified","choices":["preganglionic parasympathetic neurons","postganglionic sympathetic neurons","somatic motor neurons","sensory neurons"],"answer":1,"exp":"Chromaffin cells resemble modified postganglionic sympathetic neurons."},{"q":"The adrenal medulla secretes primarily","choices":["aldosterone and cortisol","epinephrine and norepinephrine","insulin and glucagon","TSH and ACTH"],"answer":1,"exp":"The medulla secretes epinephrine and norepinephrine."},{"q":"A prominent histologic feature of the adrenal medulla is a","choices":["central vein","central colloid-filled follicle","pancreatic duct","portal triad"],"answer":0,"exp":"A large central vein is characteristic of the medulla."},{"q":"Which endocrine organ contains follicles filled with colloid?","choices":["Pituitary","Thyroid","Parathyroid","Adrenal"],"answer":1,"exp":"The thyroid contains colloid-filled follicles."},{"q":"Which endocrine organ contains chief and oxyphil cells?","choices":["Thyroid","Parathyroid","Pancreas","Pituitary"],"answer":1,"exp":"Parathyroids contain chief and oxyphil cells."},{"q":"Which organ contains both endocrine islets and exocrine acini?","choices":["Pituitary","Pancreas","Adrenal gland","Thyroid gland"],"answer":1,"exp":"The pancreas has endocrine islets and exocrine acini."},{"q":"Which gland contains acidophils, basophils, and chromophobes?","choices":["Anterior pituitary","Thyroid","Parathyroid","Adrenal cortex"],"answer":0,"exp":"The anterior pituitary contains acidophils, basophils, and chromophobes."},{"q":"Which gland contains pituicytes and Herring bodies?","choices":["Adenohypophysis","Neurohypophysis","Thyroid","Parathyroid"],"answer":1,"exp":"The neurohypophysis contains pituicytes and Herring bodies."},{"q":"Which endocrine organ lies within the sella turcica?","choices":["Pineal gland","Pituitary gland","Thyroid gland","Adrenal gland"],"answer":1,"exp":"The pituitary lies in the sella turcica."},{"q":"Which endocrine organs are located on the posterior aspect of another endocrine gland?","choices":["Adrenal glands","Parathyroid glands","Pancreatic islets","Pituitary lobes"],"answer":1,"exp":"Parathyroids sit on the posterior surface of the thyroid."},{"q":"During ligation of the superior thyroid artery, which nerve is most at risk?","choices":["Recurrent laryngeal nerve","External laryngeal nerve","Phrenic nerve","Hypoglossal nerve"],"answer":1,"exp":"The external laryngeal nerve is at risk near the superior thyroid artery."},{"q":"During ligation of the inferior thyroid artery, which nerve is especially at risk?","choices":["External laryngeal nerve","Recurrent laryngeal nerve","Facial nerve","Glossopharyngeal nerve"],"answer":1,"exp":"The recurrent laryngeal nerve is at risk near the inferior thyroid artery."},{"q":"A patient develops hoarseness after thyroid surgery. Injury to which nerve is most likely?","choices":["Optic nerve","Recurrent laryngeal nerve","Phrenic nerve","Greater auricular nerve"],"answer":1,"exp":"Recurrent laryngeal nerve damage commonly causes hoarseness."},{"q":"A mass in the head of the pancreas causes jaundice because it compresses the","choices":["common bile duct","splenic artery","inferior vena cava","left renal vein"],"answer":0,"exp":"Pancreatic head tumors may compress the common bile duct."},{"q":"A surgeon removing the right adrenal gland must be especially careful because its short vein drains directly into the","choices":["portal vein","inferior vena cava","left renal vein","splenic vein"],"answer":1,"exp":"The right suprarenal vein drains directly to the IVC."},{"q":"A lesion of the posterior pituitary may impair release of","choices":["ACTH","TSH","ADH","GH"],"answer":2,"exp":"The posterior pituitary releases ADH."},{"q":"A pituitary tumor extending inferiorly could enter the","choices":["sphenoid sinus","maxillary sinus","frontal sinus","mastoid air cells"],"answer":0,"exp":"Inferior growth may enter the sphenoid sinus."},{"q":"A lesion involving the cavernous sinus adjacent to the pituitary could affect the","choices":["internal carotid artery and multiple cranial nerves","vertebral artery only","optic nerve only","facial artery and vein"],"answer":0,"exp":"The cavernous sinus contains the internal carotid artery and several cranial nerves."},{"q":"Accidental removal of all parathyroid tissue during thyroidectomy would most directly affect secretion of","choices":["calcitonin","PTH","TSH","ACTH"],"answer":1,"exp":"Parathyroid removal reduces PTH secretion."},{"q":"A histology slide shows pale-staining clusters surrounded by darker pancreatic acini. The pale clusters are most likely","choices":["adrenal cortical zones","pancreatic islets","thyroid follicles","pituitary basophils"],"answer":1,"exp":"Pale clusters among darker acini are pancreatic islets."}]};
